<script setup lang="ts">
import { nextTick, onMounted, reactive, ref, watch } from 'vue'
import { Plus, UserRound, LockKeyhole } from '@lucide/vue'
export type OperatorProfile = { id: string; displayName: string; role: string; canManageAccounts: boolean; createdAt?: number }
type Request = <T>(path: string, body?: unknown, method?: string) => Promise<T>
const props = defineProps<{ mode: string; profile: OperatorProfile; request: Request }>()
const emit = defineEmits<{ passwordChanged: [] }>()
const accounts = ref<OperatorProfile[]>([]), busy = ref(false), error = ref(''), success = ref(''), backupSecret = ref('')
const editing = ref<OperatorProfile | 'new' | null>(null), dialog = ref<HTMLDialogElement | null>(null)
const account = reactive({ username: '', displayName: '', password: '', confirmation: '' }), password = reactive({ currentPassword: '', newPassword: '', confirmation: '' })
async function run(work: () => Promise<void>) { busy.value = true; error.value = ''; success.value = ''; try { await work() } catch (e) { error.value = e instanceof Error ? e.message : '操作失败' } finally { busy.value = false } }
async function load() { if (props.mode === 'accounts' && props.profile.canManageAccounts) accounts.value = await props.request<OperatorProfile[]>('/accounts') }
onMounted(() => void run(load))
watch(editing, async item => { if (item) { Object.assign(account, { username: '', displayName: '', password: '', confirmation: '' }); error.value = ''; await nextTick(); dialog.value?.showModal() } })
function validate(value: string, confirmation: string) { if (value !== confirmation) throw new Error('两次输入的密码不一致'); if (value.length < 12 || value.length > 128 || !/[a-zA-Z]/.test(value) || !/[0-9]/.test(value)) throw new Error('密码须为12至128位，且包含字母和数字') }
async function saveAccount() { await run(async () => {
  validate(account.password, account.confirmation); const target = editing.value; if (!target) return
  if (target === 'new') { const result = await props.request<{ totpSecret: string }>('/accounts', { username: account.username, displayName: account.displayName, password: account.password }); backupSecret.value = result.totpSecret; success.value = '管理员已创建，请妥善保存备用动态验证密钥。' }
  else { await props.request(`/accounts/${encodeURIComponent(target.id)}/password`, { password: account.password }); success.value = `“${target.displayName}”的密码已重置，其旧登录会话已失效。` }
  editing.value = null; account.password = ''; account.confirmation = ''; await load()
}) }
async function savePassword() { await run(async () => { validate(password.newPassword, password.confirmation); await props.request('/password', { currentPassword: password.currentPassword, newPassword: password.newPassword }); Object.assign(password, { currentPassword: '', newPassword: '', confirmation: '' }); emit('passwordChanged') }) }
</script>
<template>
  <div><p v-if="error && !editing" class="error" role="alert">{{ error }}</p><p v-if="success" class="success" role="status">{{ success }}</p>
    <section v-if="mode==='accounts' && profile.canManageAccounts" class="card list-card"><div class="section-heading list-heading"><div><h2>管理员账号</h2><p>主管理员可以新增管理员及重置其密码，其他管理员只能修改自己的密码。</p></div><button class="primary" :disabled="busy" @click="editing='new'"><Plus :size="17" />新增管理员</button></div><div class="table-scroll"><table><thead><tr><th>账号</th><th>姓名 / 昵称</th><th>身份</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in accounts" :key="item.id"><td><div class="entity-cell"><span class="entity-icon"><UserRound :size="18" /></span><strong>{{ item.id }}</strong></div></td><td>{{ item.displayName }}</td><td><span class="status-badge" :class="item.role==='owner'?'enabled':''">{{ item.role==='owner'?'主管理员':'管理员' }}</span></td><td>{{ item.createdAt ? new Date(item.createdAt).toLocaleString('zh-CN') : '—' }}</td><td><button v-if="item.id!==profile.id" class="text-button" :disabled="busy" @click="editing=item">重置密码</button><span v-else class="muted">本人 · 请使用修改密码菜单</span></td></tr></tbody></table></div></section>
    <section v-if="backupSecret" class="card notice"><div class="section-heading"><h2>备用动态验证配置</h2><button @click="backupSecret=''">已保存，隐藏</button></div><p>密钥仅显示一次。启用动态验证时需先用此密钥绑定验证器；图片验证码登录模式无需使用。</p><code>{{ backupSecret }}</code></section>
    <section v-if="mode==='password'" class="card password-card"><div class="section-heading"><div><h2>修改我的密码</h2><p>{{ profile.displayName }}（{{ profile.id }}）</p></div><LockKeyhole :size="22" /></div><form @submit.prevent="savePassword"><fieldset class="package-controls" :disabled="busy"><label>原密码<input v-model="password.currentPassword" type="password" autocomplete="current-password" required /></label><label>新密码<input v-model="password.newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required /><small>12至128位，包含字母和数字。</small></label><label>确认新密码<input v-model="password.confirmation" type="password" autocomplete="new-password" required /></label><p class="muted">保存后本账号所有登录会话失效，需要使用新密码重新登录。</p><button class="primary" :disabled="busy">保存新密码</button></fieldset></form></section>
    <dialog v-if="editing" ref="dialog" class="grant-dialog account-dialog" aria-labelledby="account-title" @cancel.prevent="!busy && (editing=null)"><div class="section-heading"><h2 id="account-title">{{ editing==='new' ? '新增管理员' : '重置管理员密码' }}</h2><button :disabled="busy" @click="editing=null">关闭</button></div><p v-if="editing!=='new'">账号：{{ editing.id }} · {{ editing.displayName }}。保存后该账号的旧登录会话失效。</p><p v-if="error" class="error" role="alert">{{ error }}</p><form @submit.prevent="saveAccount"><fieldset class="package-controls" :disabled="busy"><div class="grid"><template v-if="editing==='new'"><label>登录账号<input v-model.trim="account.username" autocomplete="off" pattern="[a-zA-Z0-9][a-zA-Z0-9_.:-]*" maxlength="64" required /><small>字母、数字、下划线、点、冒号或短横线。</small></label><label>姓名 / 昵称<input v-model.trim="account.displayName" maxlength="80" required /></label></template><label>设置密码<input v-model="account.password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required /><small>12至128位，包含字母和数字。</small></label><label>确认密码<input v-model="account.confirmation" type="password" autocomplete="new-password" required /></label></div><div class="dialog-actions"><button type="button" :disabled="busy" @click="editing=null">取消</button><button class="primary" :disabled="busy">{{ editing==='new' ? '创建管理员' : '确认重置密码' }}</button></div></fieldset></form></dialog>
  </div>
</template>
